def encode(s):
    if not s:
        return ''
    result = []
    prev = s[0]
    count = 1
    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            result.append(prev + (str(count) if count > 1 else ''))
            prev = ch
            count = 1
    result.append(prev + (str(count) if count > 1 else ''))
    return ''.join(result)


def decode(s):
    result = []
    i = 0
    n = len(s)
    while i < n:
        ch = s[i]
        i += 1
        num = []
        while i < n and s[i].isdigit():
            num.append(s[i])
            i += 1
        count = int(''.join(num)) if num else 1
        result.append(ch * count)
    return ''.join(result)
